import numpy as np

# Load test data generated by build_dataset.py
data = np.load("CU_NET_random_STRESS/cu0_du0du1_stress3/test.npz")
cu = data["cu"]  # Shape: (T, 7)
cu_stress = data["cu_stress"]  # Shape: (T,)

normal_mask = cu_stress == 0
stress_mask = cu_stress == 3

feature_names = [
    "cpu",
    "mem_pct",
    "mem_bytes",
    "fs_reads",
    "fs_writes",
    "net_tx",
    "net_rx",
]

print(f"Normal rows: {normal_mask.sum()} | CU Stress rows: {stress_mask.sum()}\n")
print(
    f"{'Feature':<12} | {'Normal Mean':<12} | {'Stress Mean':<12} | {'Normal Std':<12} | {'Signal Shift (Δμ/σ)':<18}"
)
print("-" * 75)

for i, name in enumerate(feature_names):
    norm_mean = cu[normal_mask, i].mean()
    norm_std = cu[normal_mask, i].std() + 1e-8
    stress_mean = cu[stress_mask, i].mean()

    # Calculate normalized shift (Z-score difference)
    shift = abs(stress_mean - norm_mean) / norm_std
    print(
        f"{name:<12} | {norm_mean:<12.4f} | {stress_mean:<12.4f} | {norm_std:<12.4f} | {shift:<18.2f}"
    )
